CREATE TABLE leave_accrual_log (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id      UUID NOT NULL,
    employee_id    UUID NOT NULL,
    leave_type_id  UUID NOT NULL,
    period_year    INT  NOT NULL,
    period_month   INT  NOT NULL CHECK (period_month BETWEEN 1 AND 12),
    accrued_days   NUMERIC(6,2) NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_leave_accrual_period
        UNIQUE (tenant_id, employee_id, leave_type_id, period_year, period_month)
);

CREATE INDEX idx_leave_accrual_log_tenant_period
    ON leave_accrual_log (tenant_id, period_year, period_month);

ALTER TABLE leave_accrual_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE leave_accrual_log FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON leave_accrual_log
    USING (tenant_id = current_setting('app.current_tenant_id', true)::uuid);

GRANT SELECT, INSERT ON leave_accrual_log TO hr_user;
